                         ("exclusiveMinimum", lambda limit: number <= limit),
                         ("exclusiveMaximum", lambda limit: number >= limit)):
            if _is_number(schema.get(key)) and bad(_decimal(schema[key])):
                errors.append(f"{where}: violates {key}")
        if _is_number(schema.get("multipleOf")) and number % _decimal(schema["multipleOf"]) != 0:
            errors.append(f"{where}: violates multipleOf")
    if isinstance(value, str):
        if isinstance(schema.get("minLength"), int) and len(value) < schema["minLength"]:
            errors.append(f"{where}: too short")
        if isinstance(schema.get("maxLength"), int) and len(value) > schema["maxLength"]:
            errors.append(f"{where}: too long")
        if isinstance(schema.get("pattern"), str) and not re.search(schema["pattern"], value):
            errors.append(f"{where}: does not match the required pattern")
    if isinstance(value, list):
        if isinstance(schema.get("minItems"), int) and len(value) < schema["minItems"]:
            errors.append(f"{where}: too few items")
        if isinstance(schema.get("maxItems"), int) and len(value) > schema["maxItems"]:
            errors.append(f"{where}: too many items")
        if "items" in schema:
            for index, item in enumerate(value):
                errors += validate_schema(item, schema["items"], root, f"{path}.{index}" if path else str(index))
    if isinstance(value, dict):
        properties = schema.get("properties") if isinstance(schema.get("properties"), dict) else {}
        for name in schema.get("required") or []:
